// src/services/apis.js
const API_URL = "http://127.0.0.1:8000"; // ¡Sin /api al final aquí!

// Helper para añadir token automáticamente
const getAuthHeaders = () => {
  const token = localStorage.getItem("access_token");
  return token ? { Authorization: `Bearer ${token}` } : {};
};

// Función genérica con manejo de errores y token
async function request(method, endpoint, body = null) {
  const config = {
    method,
    headers: {
      "Content-Type": "application/json",
      ...getAuthHeaders(),
    },
  };

  if (body) config.body = JSON.stringify(body);

  const response = await fetch(API_URL + endpoint, config);

  // Si el token expiró, intentar refrescar (solo si usas JWT)
  if (response.status === 401) {
    localStorage.clear();
    window.location.href = "/login";
    throw new Error("Sesión expirada");
  }

  const data = await response.json();

  if (!response.ok) {
    throw new Error(data.detail || data.error || "Error en la petición");
  }

  return data;
}

export const api = {
  get: (endpoint) => request("GET", endpoint),
  post: (endpoint, body) => request("POST", endpoint, body),
  put: (endpoint, body) => request("PUT", endpoint, body),
  delete: (endpoint) => request("DELETE", endpoint),
};

// LOGIN - 100% FUNCIONAL CON DJANGO REST + SIMPLEJWT
export async function login(username, password) {
  const response = await fetch(`${API_URL}/api/token/`, {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      "Authorization": "Bearer " + accessToken,
    },
    body: JSON.stringify({ username, password }),
  });

  const data = await response.json();

  if (!response.ok) {
    throw new Error(data.detail || "Usuario o contraseña incorrectos");
  }

  // Guardamos los tokens
  localStorage.setItem("access_token", data.access);
  localStorage.setItem("refresh_token", data.refresh);
  localStorage.setItem("user", JSON.stringify(data.user || { username }));

  return data;
}

// REFRESH TOKEN
export async function refreshToken() {
  const refresh = localStorage.getItem("refresh_token");
  if (!refresh) throw new Error("No hay refresh token");

  const response = await fetch(`${API_URL}/api/token/refresh/`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ refresh }),
  });

  const data = await response.json();
  if (response.ok) {
    localStorage.setItem("access_token", data.access);
    return data.access;
  } else {
    localStorage.clear();
    window.location.href = "/login";
  }
}

// Ejemplos reales que SÍ van a funcionar con tu backend/restaurante

export const getMesas = () => api.get("/api/mesas/");
export const getEmpleados = () => api.get("/api/empleados/");
export const getPedidos = () => api.get("/api/pedidos/");
export const getProductos = () => api.get("/api/productos/");
export const crearPedido = (pedido) => api.post("/api/pedidos/", pedido);

export default api;
